def allocate_cents(total, weights):
    if isinstance(total, bool) or not isinstance(total, int):
        raise TypeError("total must be an integer")
    if total < 0:
        raise ValueError("total must be nonnegative")
    if not isinstance(weights, list):
        raise TypeError("weights must be a list")
    if not weights:
        raise ValueError("weights must not be empty")
    for weight in weights:
        if isinstance(weight, bool) or not isinstance(weight, int):
            raise TypeError("weights must contain integers")
        if weight <= 0:
            raise ValueError("weights must be positive")

    denominator = sum(weights)
    allocations = []
    remainders = []
    for weight in weights:
        numerator = total * weight
        allocations.append(numerator // denominator)
        remainders.append(numerator % denominator)

    extra = total - sum(allocations)
    order = sorted(range(len(weights)), key=lambda index: (-remainders[index], index))
    for index in order[:extra]:
        allocations[index] += 1
    return allocations

import math

def categorical_loss_grad(logits, labels):
    if not isinstance(logits, list) or not logits:
        raise ValueError("logits must be a nonempty list")
    if not isinstance(labels, list) or len(labels) != len(logits):
        raise ValueError("labels must match logits length")

    classes = None
    for row in logits:
        if not isinstance(row, list) or not row:
            raise ValueError("logits must be nonempty lists")
        if classes is None:
            classes = len(row)
        elif len(row) != classes:
            raise ValueError("logits must be rectangular")
        for value in row:
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError("logits must contain finite numbers")
            if not math.isfinite(value):
                raise ValueError("logits must contain finite numbers")
    if classes < 2:
        raise ValueError("logits must contain at least two classes")

    for label in labels:
        if isinstance(label, bool) or not isinstance(label, int):
            raise ValueError("labels must be integer class indices")
        if label < 0 or label >= classes:
            raise ValueError("label is out of range")

    count = len(logits)
    loss = 0.0
    gradient = []
    for row, label in zip(logits, labels):
        maximum = max(row)
        shifted = [math.exp(value - maximum) for value in row]
        total = sum(shifted)
        probabilities = [value / total for value in shifted]
        loss += math.log(total) + maximum - row[label]
        gradient.append([
            (probability - (1.0 if index == label else 0.0)) / count
            for index, probability in enumerate(probabilities)
        ])
    return loss / count, gradient

def check_contract(fn):
    assert fn(1) == 1
    assert fn(65535) == 65535
    assert fn(42) == 42

    for value in (0, 65536, -1):
        try:
            fn(value)
        except ValueError:
            pass
        else:
            assert False, "out-of-range integer was accepted"

    for value in (True, False, 1.5, "80", None):
        try:
            fn(value)
        except TypeError:
            pass
        else:
            assert False, "invalid type was accepted"
